export interface ConnectorConfig {
  /** Salesforce instance identifier (e.g., 'na1', 'eu11', or 'MyDomainName.my') */
  instance: string
  /** Salesforce access token for Bearer authentication */
  accessToken: string
  /** Optional injected fetch for testing */
  fetch?: typeof fetch
}

export interface HubSpotDealWebhookPayload {
  dealId: string
  properties: {
    dealname: string
    dealamount: string
    domain: string
  }
}

export interface UpsertResult {
  accountId: string
  created: boolean
  success: boolean
}

async function handle(
  payload: HubSpotDealWebhookPayload,
  config: ConnectorConfig
): Promise<UpsertResult> {
  const fetchImpl = config.fetch ?? fetch

  // Validate required fields
  if (!payload.dealId) {
    throw new Error('Missing required field: dealId')
  }
  if (!payload.properties) {
    throw new Error('Missing required field: properties')
  }
  if (!payload.properties.dealname) {
    throw new Error('Missing required field: properties.dealname')
  }
  if (!payload.properties.dealamount) {
    throw new Error('Missing required field: properties.dealamount')
  }
  if (!payload.properties.domain) {
    throw new Error('Missing required field: properties.domain')
  }

  const { dealname, dealamount, domain } = payload.properties

  // Build Salesforce upsert URL
  const url = `https://${config.instance}.salesforce.com/services/data/v68.0/sobjects/Account/Website/${encodeURIComponent(domain)}`

  // Prepare request body
  const body = {
    Name: dealname,
    Website: domain,
    AnnualRevenue: Number(dealamount)
  }

  const response = await fetchImpl(url, {
    method: 'PATCH',
    headers: {
      'Authorization': `Bearer ${config.accessToken}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(body)
  })

  if (!response.ok) {
    throw new Error(`Salesforce upsert failed: ${response.status} ${response.statusText} for PATCH ${url}`)
  }

  const result = await response.json() as { id: string; created?: boolean; success: boolean; errors?: unknown[] }

  if (!result.success || result.errors?.length) {
    throw new Error(`Salesforce upsert returned error: ${JSON.stringify(result.errors)}`)
  }

  return {
    accountId: result.id,
    created: result.created ?? false,
    success: true
  }
}

